function cut(img,col,row,cols,rows,trim=false){const cw=img.width/cols,ch=img.height/rows,c=make(Math.floor(cw),Math.floor(ch)),g=c.getContext('2d');g.drawImage(img,cw*col,ch*row,cw,ch,0,0,c.width,c.height);const data=g.getImageData(0,0,c.width,c.height);let minx=c.width,miny=c.height,maxx=0,maxy=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++){const at=(y*c.width+x)*4;if(data.data[at+3]<24)data.data[at+3]=0;if(data.data[at+3]>50){minx=Math.min(minx,x);miny=Math.min(miny,y);maxx=Math.max(maxx,x);maxy=Math.max(maxy,y)}}g.putImageData(data,0,0);if(trim&&maxx>minx){const t=make(maxx-minx+3,maxy-miny+3);t.getContext('2d').drawImage(c,minx,miny,maxx-minx+1,maxy-miny+1,1,1,maxx-minx+1,maxy-miny+1);return t}return c}
